      "content": "{\n  \"name\": \"dsh-jev-guard\",\n  \"version\": \"0.5.7\",\n  \"description\": \"Pre-execution safety valve for DeepSeek Harness: a TypeSafe Jev question decides whether a shell command/script would irreversibly delete or overwrite real data. Four states (allow/revise/block/escalate), mounted on tools/pre-execute. Zero dependencies; WSL/Linux (bash) and Windows (pwsh); one-shot tokens, credit-exhaustion degradation, shared audit log; bilingual (zh-CN / en) messages.\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"cordis\",\n    \"guard\",\n    \"safety\",\n    \"destructive-command\",\n    \"jev\",\n    \"typesafe\",\n    \"pre-execute\",\n    \"audit-log\"\n  ],\n  \"type\": \"module\",\n  \"main\": \"adapters/dsh/index.js\",\n  \"exports\": {\n    \".\": \"./adapters/dsh/index.js\",\n    \"./gate\": \"./lib/gate.js\",\n    \"./rules\": \"./lib/rules.js\",\n    \"./verdict\": \"./lib/verdict.js\",\n    \"./audit\": \"./lib/audit.js\",\n    \"./token\": \"./lib/token.js\",\n    \"./quota\": \"./lib/quota.js\",\n    \"./cli\": \"./bin/guard.mjs\",\n    \"./adapters/dsh\": \"./adapters/dsh/index.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"bin\": {\n    \"jev-guard\": \"bin/guard.mjs\"\n  },\n  \"scripts\": {\n    \"selftest\": \"node bin/guard.mjs selftest\",\n    \"rules\": \"node bin/guard.mjs rules\",\n    \"judge\": \"node bin/guard.mjs judge\",\n    \"status\": \"node bin/guard.mjs status\",\n    \"log\": \"node bin/guard.mjs log --stats\"\n  },\n  \"engines\": {\n    \"node\": \">=20.0.0\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"files\": [\n    \"bin\",\n    \"lib\",\n    \"adapters\",\n    \"docs\",\n    \"tools\",\n    \"cordis.patch.yml\",\n    \"config.example.json\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"DEPLOY.md\",\n    \"DEPLOY.zh-CN.md\",\n    \"CHANGELOG.md\",\n    \"CHANGELOG.zh-CN.md\",\n    \"START-HERE.md\",\n    \"START-HERE.zh-CN.md\"\n  ],\n  \"license\": \"MIT\",\n  \"author\": \"7starsseeker\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/7starsseeker/dsh-jev-guard.git\"\n  },\n  \"homepage\": \"https://github.com/7starsseeker/dsh-jev-guard#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/7starsseeker/dsh-jev-guard/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  }\n}\n"
